interface Invoice {
  id: string;
  vendor: string;
  amount: number;
}

interface BankLine {
  ref: string;
  payee: string;
  amount: number;
}

interface ReconcileInput {
  invoices: Invoice[];
  bank: BankLine[];
}

interface ReconcileResult {
  matched: number;
  fuzzy: number;
  unmatched: number;
  unmatchedTotal: number;
}

function normalizeName(name: string): string {
  const cleaned: string = name.toLowerCase().replace(/[^a-z0-9 ]/g, "");
  const parts: string[] = cleaned.split(" ");
  const kept: string[] = [];
  for (let i = 0; i < parts.length; i++) {
    const w: string = parts[i];
    if (w === "inc" || w === "llc" || w === "ltd" || w === "gmbh" || w === "co") {
      continue;
    }
    kept.push(w);
  }
  return kept.join(" ").trim();
}

function levenshtein(a: string, b: string): number {
  const m: number = a.length;
  const n: number = b.length;
  if (m === 0) {
    return n;
  }
  if (n === 0) {
    return m;
  }
  let prev: number[] = [];
  let curr: number[] = [];
  for (let j = 0; j <= n; j++) {
    prev.push(j);
    curr.push(0);
  }
  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    const ca: string = a.charAt(i - 1);
    for (let j = 1; j <= n; j++) {
      const cost: number = ca === b.charAt(j - 1) ? 0 : 1;
      const del: number = prev[j] + 1;
      const ins: number = curr[j - 1] + 1;
      const sub: number = prev[j - 1] + cost;
      let best: number = del;
      if (ins < best) {
        best = ins;
      }
      if (sub < best) {
        best = sub;
      }
      curr[j] = best;
    }
    const tmp: number[] = prev;
    prev = curr;
    curr = tmp;
  }
  return prev[n];
}

export function run(input: string): string {
  const data: ReconcileInput = JSON.parse(input) as ReconcileInput;
  const invoices: Invoice[] = data.invoices ? data.invoices : [];
  const bank: BankLine[] = data.bank ? data.bank : [];

  const used: boolean[] = [];
  const normVendors: string[] = [];
  for (let i = 0; i < invoices.length; i++) {
    used.push(false);
    normVendors.push(normalizeName(invoices[i].vendor));
  }

  let matched: number = 0;
  let fuzzy: number = 0;
  let unmatched: number = 0;
  let unmatchedTotal: number = 0;

  for (let b = 0; b < bank.length; b++) {
    const line: BankLine = bank[b];
    const payee: string = normalizeName(line.payee);
    const tolerance: number = Math.abs(line.amount) * 0.01;

    let bestIndex: number = -1;
    let bestScore: number = 0;

    for (let i = 0; i < invoices.length; i++) {
      if (used[i]) {
        continue;
      }
      const diff: number = Math.abs(invoices[i].amount - line.amount);
      if (diff > tolerance) {
        continue;
      }
      const score: number = levenshtein(normVendors[i], payee) * 1000 + diff;
      if (bestIndex === -1 || score < bestScore) {
        bestIndex = i;
        bestScore = score;
      }
    }

    if (bestIndex !== -1 && bestScore < 4000) {
      used[bestIndex] = true;
      if (bestScore < 1) {
        matched++;
      } else {
        fuzzy++;
      }
    } else {
      unmatched++;
      unmatchedTotal += line.amount;
    }
  }

  const result: ReconcileResult = {
    matched: matched,
    fuzzy: fuzzy,
    unmatched: unmatched,
    unmatchedTotal: Math.round(unmatchedTotal * 100) / 100,
  };
  return JSON.stringify(result);
}
